#!/usr/bin/env python3
"""Bundle original poodle assets for both HTTP and local-file previews.
Run after changing either SVG source or exporting app-motion.json.
"""
import json
from pathlib import Path

assets = Path(__file__).resolve().parents[1] / "assets/mongram/poodle"
payload = {pose: (assets / f"{pose}.svg").read_text() for pose in ("seated", "resting")}
payload["motion"] = json.loads((assets / "app-motion.json").read_text())
(assets / "browser-motion.js").write_text(
    "// Generated by scripts/bundle-mongram-motion.py; do not edit by hand.\n"
    + "window.mongramMotionAssets=" + json.dumps(payload, separators=(",", ":")) + ";\n"
)
print("Bundled two SVG poses and eight original motion tracks.")
